<script setup lang="ts">
import { computed, onMounted, ref, watch } from "vue";
import router from "@/router";
import { ParseContestReplayImportPreview, PostContestReplayContestCreate, PostContestReplayContestPreview } from "@/apis/contest.ts";
import { useCurrentInstance } from "@/util";
import { ShowErrorTips, ShowTextTipsError, ShowTextTipsInfo, ShowTextTipsSuccess, ShowTextTipsWarn } from "@/util/tips";
import { useWebStyleStore } from "@/stores/webStyle.ts";
import { useUserStore } from "@/stores/user.ts";
import { AuthType } from "@/auth";
import { useBreakpoint } from "@/composables/useBreakpoint";
import type { ContestReplayImportPreview } from "@/types/contest.ts";
import ParseProblemList from "@/components/problem/ParseProblemList.vue";
import { GetTimeStringBySeconds } from "@/time/library.ts";
import {
  buildReplayPreviewMatrix,
  buildReplayProblemMap,
  buildSampleReplayCsv,
  contestProblemLabel,
  describeReplayPreview,
  resolvePreviewMapping,
} from "@/views/contest/contest-replay-common.ts";
import { saveAs } from "file-saver";

// 新建回放比赛：填标题 → 选题目 → 上传榜单 CSV → 预览验证 → 创建 → 跳该回放比赛详情页。
//
// 与「在某场比赛里上传榜单」的区别：这里的目标比赛尚不存在，榜单是**这场回放比赛自己的成绩本体**，
// 因此题目集合在创建时一并确定（题目顺序即 CSV 题目列顺序），后端在同一事务里建
// contest + 题目 + 中立本体 + 自关联行（设计文档 §4.1 / §4.2）。
//
// 交互上的几条硬约束（这几条都是踩过坑才补的）：
//   1. 只有 i-manage-contest 才能进：否则用户会填完题目、选完文件，最后一次上传才被 AuthError 拒掉；
//   2. 文件格式契约必须写在界面上：否则用户拿平台「导出榜单」（.xlsx + `00:12:34 (-2)` 写法）来传，
//      格子全部无法解析，却只看到「解析成功」的预览；
//   3. 预览必须能验证：展示文件名、成绩矩阵与分级诊断，零有效成绩时直接禁用创建，
//      不能让「有选手、零成绩」的榜单落库成一场空回放；
//   4. 题目变更不要逼用户重传文件：缓存上次选中的文件，自动按新题目集合重新解析对齐。

const { globalProperties } = useCurrentInstance();
const webStyleStore = useWebStyleStore();
const userStore = useUserStore();
const { isMobile } = useBreakpoint();

// 后端榜单文件上限（与 foundationservice.ReplayImportMaxBytes 同口径）
const REPLAY_IMPORT_MAX_BYTES = 20 * 1024 * 1024;
const REPLAY_IMPORT_MAX_MB = REPLAY_IMPORT_MAX_BYTES / 1024 / 1024;

// 上传/创建是管理员操作，与后端 i-manage-contest 门禁同口径
const canManageContest = computed(() => userStore.hasAuth(AuthType.ManageContest));

const contestReplayForm = ref({
  title: "",
  problems: [] as number[],
  // 可见性：回放榜单常含真实选手成绩，必须由创建者显式选择；默认公开保持存量行为
  private: false,
});

const fileInput = ref<HTMLInputElement | null>(null);
const preview = ref<ContestReplayImportPreview | null>(null);
// 源列序号 → 目标题目序号；某项被清空即「忽略该题」，不会进请求体
const previewMapping = ref<Record<number, number>>({});
const previewVisible = ref(false);
const previewing = ref(false);
const creating = ref(false);
// 创建成功后锁住按钮：比赛已落库，重复点击会再建一场
const createLocked = ref(false);
// 上次选中的文件：题目变更时用它自动重新解析，避免「改个题目就要重传文件」
const lastFile = ref<File | null>(null);

// 题目为空时不允许上传：后端按题目列对齐，没有题目就没有对齐基准
const canUpload = computed(() => contestReplayForm.value.problems.length > 0);

// 预览诊断（致命 / 可疑两级）
const diagnosis = computed(() => (preview.value ? describeReplayPreview(preview.value) : null));

// 成绩矩阵：按源列顺序回显前若干行，让管理员一眼核对成绩是否错位
const previewMatrix = computed(() => {
  const current = preview.value;
  if (!current) {
    return { rows: [], total: 0, truncated: false };
  }
  return buildReplayPreviewMatrix(current.participants, current.sourceProblems.length, isMobile.value ? 5 : 8);
});

// 当前映射压缩结果（提交口径）：空映射不能创建
const currentProblemMap = computed(() => buildReplayProblemMap(previewMapping.value));

// 创建被阻断的原因：空串表示可以创建
const createBlockedReason = computed(() => {
  const current = preview.value;
  if (!current) {
    return "请先上传榜单文件并确认预览";
  }
  if (diagnosis.value?.hasFatal) {
    return diagnosis.value.fatalReason;
  }
  if (currentProblemMap.value.length === 0) {
    return "请至少为榜单的一个题目列选择本场题目（全部清空会让回放榜单没有任何成绩）";
  }
  return "";
});
const canCreate = computed(() => !createLocked.value && createBlockedReason.value === "");

// 下载示例榜单 CSV：按已选题目数生成 A/B/C… 列与样例选手
const handleDownloadSampleCsv = () => {
  const problemCount = Math.max(contestReplayForm.value.problems.length, 1);
  const csv = buildSampleReplayCsv(problemCount);
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
  saveAs(blob, "replay-contest-standings-sample.csv");
};

// 上传并解析：失败一律给可见提示（原先 catch 只 console.error，用户看到的是「点了没反应」）
const uploadFile = async (file: File) => {
  if (!canUpload.value) {
    ShowTextTipsWarn(globalProperties, "请先选择题目，榜单题目列要与所选题目对齐");
    return;
  }
  if (file.size > REPLAY_IMPORT_MAX_BYTES) {
    ShowTextTipsError(globalProperties, `文件超过 ${REPLAY_IMPORT_MAX_MB}MB 上限，请拆分后再上传`);
    return;
  }

  previewing.value = true;
  try {
    const res = await PostContestReplayContestPreview(contestReplayForm.value.problems, file);
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      preview.value = null;
      previewVisible.value = false;
      return;
    }
    const parsed = ParseContestReplayImportPreview(res.data);
    preview.value = parsed;
    previewMapping.value = resolvePreviewMapping(parsed.sourceProblems.length, parsed.targetProblems.length, parsed.problemMap);
    // 标题留空时用后端按榜单文件名给的标题建议兜底，用户仍可在表单里改
    if (!contestReplayForm.value.title.trim() && parsed.titleSuggestion) {
      contestReplayForm.value.title = parsed.titleSuggestion;
    }
    previewVisible.value = true;
  } catch (err) {
    // 网络异常 / 响应结构异常：不能静默，否则用户完全不知道发生了什么
    console.error("replay contest preview failed", err);
    ShowTextTipsError(globalProperties, "榜单解析失败：请检查网络后重试，或换一个文件");
    preview.value = null;
    previewVisible.value = false;
  } finally {
    previewing.value = false;
  }
};

// 选择文件后上传解析并打开预览弹窗
const handleFileChange = async (e: Event) => {
  const input = e.target as HTMLInputElement;
  const file = input.files?.[0];
  try {
    if (!file) {
      return;
    }
    lastFile.value = file;
    await uploadFile(file);
  } finally {
    if (input) {
      input.value = "";
    }
  }
};

// 用上次的文件重新解析（题目集合变化后重新对齐，不让用户重选文件）
const handleReParse = async () => {
  const file = lastFile.value;
  if (!file) {
    ShowTextTipsInfo(globalProperties, "还没有上传过文件，请先选择榜单文件");
    return;
  }
  await uploadFile(file);
};

// 取消预览：丢弃本次解析（预览的题目对齐基于当时的题目集合，留着会让「创建」用看不见的旧映射）
const handlePreviewCancel = () => {
  previewVisible.value = false;
  preview.value = null;
  previewMapping.value = {};
};

// 创建回放比赛：题目与映射随请求一起提交（后端以本次请求为准重新校验，防篡改）
const handleCreate = async () => {
  if (creating.value || createLocked.value) {
    return;
  }
  const title = contestReplayForm.value.title.trim();
  if (!title) {
    ShowTextTipsError(globalProperties, "请填写回放比赛标题");
    return;
  }
  if (!canUpload.value) {
    ShowTextTipsError(globalProperties, "请先选择题目，榜单题目列要与所选题目对齐");
    return;
  }
  const currentPreview = preview.value;
  if (!currentPreview) {
    ShowTextTipsError(globalProperties, "请先上传榜单文件并确认预览");
    return;
  }
  if (createBlockedReason.value) {
    ShowTextTipsError(globalProperties, createBlockedReason.value);
    return;
  }

  creating.value = true;
  try {
    const res = await PostContestReplayContestCreate(
      title,
      contestReplayForm.value.problems,
      currentPreview.previewId,
      currentProblemMap.value,
      contestReplayForm.value.private
    );
    if (res.code !== 0) {
      ShowErrorTips(globalProperties, res.code);
      return;
    }

    const newId = Number(res.data?.contest_id ?? 0);
    if (newId <= 0) {
      // 兜底：比赛可能已经建出来，拿不到 ID 就不能跳一个坏地址，锁住创建防重复
      createLocked.value = true;
      ShowTextTipsError(globalProperties, "创建成功但未获取到比赛 ID，请到比赛列表确认");
      return;
    }

    createLocked.value = true;
    previewVisible.value = false;
    ShowTextTipsSuccess(globalProperties, "创建成功");

    await router.push({
      name: "contest-detail",
      params: { contestId: newId },
    });
  } catch (err) {
    console.error("replay contest create failed", err);
    ShowTextTipsError(globalProperties, "创建失败：请检查网络后重试；若持续失败请刷新页面确认比赛是否已创建");
  } finally {
    creating.value = false;
  }
};

onMounted(() => {
  webStyleStore.setTitle("新建回放比赛 - " + webStyleStore.getTitle);
});

// 题目集合变化会让已解析的预览失效（预览里的题目列对齐是按旧题目集合算的）。
// 这里不逼用户重传：有缓存文件就自动按新题目集合重新解析，没有才退回「请重新上传」。
watch(
  () => contestReplayForm.value.problems.join(","),
  async () => {
    const file = lastFile.value;
    if (!preview.value) {
      return;
    }
    preview.value = null;
    previewMapping.value = {};
    previewVisible.value = false;
    if (!file || !canUpload.value) {
      ShowTextTipsWarn(globalProperties, "题目已变更，请重新上传榜单文件");
      return;
    }
    ShowTextTipsInfo(globalProperties, "题目已变更，正在按新题目重新对齐榜单…");
    await uploadFile(file);
  }
);
</script>

<template>
  <t-row>
    <t-col :span="isMobile ? 12 : 8">
      <div style="margin: 10px">
        <t-card>
          <!-- 权限门禁：没有 i-manage-contest 就不该让用户走完整个流程才被拒 -->
          <t-alert
            v-if="!canManageContest"
            theme="error"
            message="没有比赛管理权限，无法新建回放比赛"
            description="新建回放比赛需要「比赛管理」权限（i-manage-contest）。如需操作，请联系管理员为你开通。"
          />

          <t-form v-else :model="contestReplayForm" :label-align="isMobile ? 'top' : 'right'" label-width="150px">
            <t-form-item label="标题">
              <t-input v-model="contestReplayForm.title" placeholder="例如「2024 校内选拔赛」" :maxlength="75"></t-input>
            </t-form-item>
            <t-form-item label="可见性">
              <t-space direction="vertical" size="small" style="width: 100%">
                <t-radio-group v-model="contestReplayForm.private">
                  <t-radio :value="false">公开</t-radio>
                  <t-radio :value="true">私有</t-radio>
                </t-radio-group>
                <span class="dida-replay-create-hint">
                  {{
                    contestReplayForm.private
                      ? "私有：仅管理员可见，普通用户不会在比赛列表里看到这场回放"
                      : "公开：所有用户都能在比赛列表看到这场回放（榜单含选手昵称与成绩）"
                  }}
                </span>
              </t-space>
            </t-form-item>
            <t-form-item label="题目">
              <t-space direction="vertical" size="small" style="width: 100%">
                <t-alert
                  v-if="!canUpload"
                  theme="info"
                  message="请先选择题目：榜单文件的题目列要按下方顺序与这些题目一一对齐"
                />
                <ParseProblemList v-model="contestReplayForm.problems" show-index />
                <span class="dida-replay-create-hint">
                  题目顺序就是榜单文件的列顺序：第 1 题对应文件里的 A 列，第 2 题对应 B 列，以此类推。
                </span>
              </t-space>
            </t-form-item>
            <t-form-item label="榜单文件">
              <t-space direction="vertical" size="small" style="width: 100%">
                <div class="dida-replay-format">
                  <div class="dida-replay-format-title">文件格式（不符合会解析失败或成绩为空）</div>
                  <ul class="dida-replay-format-list">
                    <li>必需列：<code>Handle</code> / <code>用户名</code> / <code>账号</code> 之一；可选 <code>Nickname</code> / <code>昵称</code></li>
                    <li>题目列：表头为单个字母 <code>A</code>、<code>B</code>、<code>C</code>…，按顺序对应上面的题目</li>
                    <li>
                      题目格：<code>+mm:ss</code> 通过（相对比赛开始的时刻）、<code>-次数</code> 未通过、<code>.</code> 或留空 未提交
                    </li>
                    <li>分隔符支持逗号 / 分号 / 制表符；编码 UTF-8（可带 BOM）；文件 ≤ {{ REPLAY_IMPORT_MAX_MB }}MB</li>
                    <li>以 <code>#</code> 开头的说明行会被忽略，可以直接写在文件开头</li>
                    <li class="dida-replay-format-warn">
                      平台「导出榜单」是 .xlsx，请先另存为 CSV 再上传；其题目格写法
                      <code>09:12:34 (-2)</code> / <code>(-3)</code> 已支持，无需手工改写
                    </li>
                  </ul>
                </div>
                <t-space size="small" wrap>
                  <t-button variant="outline" :disabled="!canUpload" :loading="previewing" @click="fileInput?.click()">
                    上传榜单文件
                  </t-button>
                  <t-button variant="text" :disabled="!canUpload" @click="handleDownloadSampleCsv">下载示例 CSV</t-button>
                  <t-button v-if="lastFile" variant="text" :loading="previewing" :disabled="!canUpload" @click="handleReParse">
                    重新解析「{{ lastFile.name }}」
                  </t-button>
                </t-space>
              </t-space>
            </t-form-item>
            <t-form-item v-if="!isMobile" label=" ">
              <t-space>
                <t-button theme="primary" :loading="creating" :disabled="!canCreate" @click="handleCreate">创建</t-button>
              </t-space>
            </t-form-item>
          </t-form>
        </t-card>
      </div>
    </t-col>
    <t-col :span="isMobile ? 12 : 4">
      <div style="margin: 12px">
        <div v-if="isMobile" class="dida-replay-create-container">
          <t-button theme="primary" block :loading="creating" :disabled="!canCreate" @click="handleCreate">创建</t-button>
        </div>
        <t-card>
          <p class="dida-replay-create-hint">
            回放比赛的成绩来自上传的榜单文件，不能提交；创建出来即已结束，可在普通比赛的「回放关联」里把它作为源比赛关联。
          </p>
        </t-card>
      </div>
    </t-col>
  </t-row>

  <!-- 文件选择框常驻：按钮只是触发器，解析结果进预览弹窗 -->
  <input ref="fileInput" type="file" accept=".csv,text/csv" style="display: none" @change="handleFileChange" />

  <t-dialog
    v-model:visible="previewVisible"
    header="榜单预览"
    :confirm-btn="canCreate ? '创建' : null"
    :confirm-loading="creating"
    :width="isMobile ? '92%' : 780"
    @confirm="handleCreate"
    @cancel="handlePreviewCancel"
  >
    <div v-if="preview" class="dida-replay-preview">
      <t-space size="small" direction="vertical" style="width: 100%">
        <!-- 文件回显：让管理员能确认「传的是哪份文件」 -->
        <div v-if="preview.filename" class="dida-replay-preview-file">
          文件：<strong>{{ preview.filename }}</strong>
        </div>

        <div>
          识别到 <strong>{{ preview.participants.length }}</strong> 名选手（其中
          <strong>{{ diagnosis?.scoredPlayers ?? 0 }}</strong> 人有成绩）、
          <strong>{{ preview.sourceProblems.length }}</strong> 道题<template v-if="preview.durationSec > 0"
            >，榜单时长约 {{ GetTimeStringBySeconds(preview.durationSec) }}</template
          >。
        </div>

        <!-- 致命：零有效成绩 / 零选手，直接阻断创建，不让空榜落库 -->
        <t-alert v-if="diagnosis?.hasFatal" theme="error" :message="diagnosis.fatalReason" />

        <!-- 可疑：不阻断，但要显眼，让管理员自己判断 -->
        <div v-if="diagnosis && diagnosis.suspects.length" class="dida-replay-suspects">
          <div class="dida-replay-suspects-title">需要确认</div>
          <ul class="dida-replay-format-list">
            <li v-for="(suspect, idx) in diagnosis.suspects" :key="idx">{{ suspect }}</li>
          </ul>
        </div>

        <div class="dida-replay-preview-title">题目映射（榜单题目列 → 本回放比赛题目）</div>
        <div v-for="source in preview.sourceProblems" :key="source.index" class="dida-replay-preview-row">
          <span class="dida-replay-preview-source">{{ contestProblemLabel(source.index + 1) }}</span>
          <span class="dida-replay-preview-arrow">→</span>
          <t-select v-model="previewMapping[source.index]" placeholder="忽略该题" auto-width clearable>
            <t-option
              v-for="target in preview.targetProblems"
              :key="target.index"
              :value="target.index"
              :label="`${contestProblemLabel(target.index)}. ${target.title}`"
            />
          </t-select>
        </div>
        <div v-if="currentProblemMap.length === 0" class="dida-replay-preview-blocked">
          所有题目列都被忽略了：回放榜单将没有任何成绩，请至少保留一列。
        </div>

        <!-- 成绩矩阵：把解析结果按榜单格子口径回显，列错位/成绩全空一眼可见 -->
        <template v-if="previewMatrix.rows.length">
          <div class="dida-replay-preview-title">成绩预览（按当前映射前的文件内容）</div>
          <div class="dida-replay-matrix-wrap">
            <table class="dida-replay-matrix">
              <thead>
                <tr>
                  <th>选手</th>
                  <th v-for="source in preview.sourceProblems" :key="source.index">{{ contestProblemLabel(source.index + 1) }}</th>
                </tr>
              </thead>
              <tbody>
                <tr v-for="(row, rowIdx) in previewMatrix.rows" :key="rowIdx">
                  <td>{{ row.label }}</td>
                  <td v-for="(cell, cellIdx) in row.cells" :key="cellIdx" class="dida-replay-matrix-cell">{{ cell }}</td>
                </tr>
              </tbody>
            </table>
          </div>
          <div v-if="previewMatrix.truncated" class="dida-replay-create-hint">
            共 {{ previewMatrix.total }} 名选手，这里只显示前 {{ previewMatrix.rows.length }} 名。
          </div>
        </template>

        <!-- 解析提示：默认折叠，条数多时也不糊住关键信息 -->
        <details v-if="preview.warnings.length" class="dida-replay-warnings">
          <summary>解析提示（{{ preview.warnings.length }} 条）</summary>
          <ul class="dida-replay-format-list">
            <li v-for="(warning, idx) in preview.warnings" :key="idx">{{ warning }}</li>
          </ul>
        </details>

        <div v-if="createBlockedReason" class="dida-replay-preview-blocked">无法创建：{{ createBlockedReason }}</div>
      </t-space>
    </div>
  </t-dialog>
</template>

